"""
    Example of using all_wheels_on_track and speed
    """
def speed(params: Any) -> object {
    all_wheels_on_track = params['all_wheels_on_track'];
    speed = params['speed'];
    SPEED_THRESHOLD = 1.0;
    if not all_wheels_on_track {
        reward = 0.001;
    } elif (speed < SPEED_THRESHOLD) {
        reward = 0.5;
    } else {
        reward = 1.0;
    }
    return reward;
}

