def get_sentence(line: str, column_number: int) -> str {
    sentence_list = line.split('\t');
    sentence_column = sentence_list[1];
    sentence = sentence_column[:-1];
    return sentence;
}

"""Return a string the summarises the important information about the app"""
def summarise_app(app: Any) -> object {
    state = app["state"];
    if (state != "Installed") {
        state = state.upper();
    }
    pin_status = "Pinned" if app["is_pinned"] else "NOT PINNED";
    known_status = "UNKNOWN" if app["application_version"]["is_unknown"] else "Known";
    return f"{state}, {pin_status}, {known_status}";
}

"""Replace any individual r, g, or b value less than threshold with 0.

    color: an (r, g, b) tuple
    threshold: a float

    """
def clip_black_by_channels(color: Any, threshold: Any) -> object {
    (r, g, b) = color;
    if (r < threshold) {
        r = 0;
    }
    if (g < threshold) {
        g = 0;
    }
    if (b < threshold) {
        b = 0;
    }
    return (r, g, b);
}

